  ui_story_5062_50620102_80_dialog_content = "Que tal você considerar esta medalha como um presente de agradecimento do povo de Crepúsculo?",
  ui_story_5062_50620102_81_dialog_content = "Esqueça a tarefa. Reconstruir Crepúsculo, por si só, é uma façanha que mudará a vida dos moradores locais.",
  ui_story_5062_50620102_82_dialog_content = "Mesmo que eu quase tenha entrado em um frenesi louco e destruído este lugar?",
