  ui_story_5062_50620102_89_dialog_content = "Caminhe comigo, Celestita. Vamos dar uma olhada no Crepúsculo que ajudamos a reconstruir.",
  ui_story_5062_50620103_1_dialog_content = "Aqui é Wrath. Por favor, responda se você pode me ouvir.",
  ui_story_5062_50620103_2_dialog_content = "Entendido. Este é o Gram.",
  ui_story_5062_50620103_3_dialog_content = "Informe sua situação atual.",
  ui_story_5062_50620103_4_dialog_content = "No perímetro da área da missão, preparando para entrar.",
  ui_story_5062_50620103_5_dialog_content = "As comunicações estão claras e os suprimentos são suficientes. Até agora, tudo bem... exceto...",
  ui_story_5062_50620103_6_dialog_content = "Exceto o quê?",
  ui_story_5062_50620103_7_dialog_content = "Exceto que Benny e Revy estão constantemente competindo entre si pela chance de lutar contra alguns Eclipsitas.",
  ui_story_5062_50620103_8_dialog_content = "Eles são excelentes lutadores quando se trata de seus talentos individuais e a escolha ideal para uma missão de exploração em pequena escala como esta.",
  ui_story_5062_50620103_9_dialog_content = "Mas nossa oficial de inteligência afirma que eles são tão barulhentos que ela nem consegue dormir tranquilamente à noite!",
  ui_story_5062_50620103_10_dialog_content = "Hmm... Quando se trata de lidar com informações, ninguém chega nem perto dela.",
  ui_story_5062_50620103_11_dialog_content = "Ah sim, e parece haver algo estranho flutuando ao redor de Chandra.",
  ui_story_5062_50620103_12_dialog_content = "O ambiente desta operação é especial. Portanto, o aconselhamento psicológico é essencial para o pessoal de combate.",
  ui_story_5062_50620103_13_dialog_content = "Quanto a outros problemas, eles podem ser ignorados por enquanto.",
  ui_story_5062_50620103_14_dialog_content = "Entendido. Então todas as coisas estão bem.",
  ui_story_5062_50620103_15_dialog_content = "OK. Agora deixe-me resumir sua missão mais uma vez.",
  ui_story_5062_50620103_16_dialog_content = "Desta vez, você começará em Crepúsculo, seguindo para explorar as fronteiras da noite eterna.",
  ui_story_5062_50620103_17_dialog_content = "Devemos monitorar a atividade dos Eclipsitas o mais de perto possível para evitar outro ataque surpresa.",
  ui_story_5062_50620103_18_dialog_content = "Entendi.",
  ui_story_5062_50620103_19_dialog_content = "Vou sincronizar as coordenadas dos locais de exploração deste plano com você mais tarde.",
  ui_story_5062_50620103_20_dialog_content = "Quanto a ocorrências não planejadas, você terá que usar sua experiência e se adaptar à situação de acordo.",
  ui_story_5062_50620103_21_dialog_content = "Pensar rápido — meu tipo favorito.",
  ui_story_5062_50620103_22_dialog_content = "Não se esqueça, esta é uma missão de exploração. Apenas faça seu trabalho de reconhecimento.",
  ui_story_5062_50620103_23_dialog_content = "Então, se encontrarmos o inimigo, devemos guardar o heroísmo para outro dia e recuar imediatamente, certo?",
  ui_story_5062_50620103_24_dialog_content = "Sim. Tenho confiança de que você será capaz de lidar com qualquer situação que aparecer no seu caminho.",
  ui_story_5062_50620103_25_dialog_content = "O quê?! Recuar?! Por que não explodimos todos eles em pedacinhos! Cabuum!",
  ui_story_5062_50620103_26_dialog_content = "Chega... Ainda se lembra do objetivo da missão? Não era para—",
  ui_story_5062_50620103_27_dialog_content = "Que tal uma pequena aposta? Vamos ver quem consegue derrubar mais Eclipsitas! O que você acha?!",
  ui_story_5062_50620103_28_dialog_content = "Ei! Não balance suas armas assim!",
  ui_story_5062_50620103_29_dialog_content = "Você está dentro! Kuro, conte pra mim, pode ser?",
  ui_story_5062_50620103_30_dialog_content = "Desculpe, Capitã, vou segurar os dois...",
  ui_story_5062_50620103_31_dialog_content = "Deixe-me ajudar!",
  ui_story_5062_50620103_32_dialog_content = "Benny, não mexa nessa mala! Essas são nossas rações!",
  ui_story_5062_50620103_33_dialog_content = "Hmm? Ouvi alguém dizer \"rações\", miau?",
  ui_story_5062_50620103_34_dialog_content = "Peixe seco! Peixe seco!",
  ui_story_5062_50620103_35_dialog_content = "Não tem peixe seco aqui! As rações de combate precisam ser ricas em calorias. Tudo que você vê aqui foi preparado por mim mesmo.",
  ui_story_5062_50620103_36_dialog_content = "Esse cheiro... Esse cheiro! Miau... Será que...?",
  ui_story_5062_50620103_37_dialog_content = "Parece ser algum tipo de produto de queijo.",
  ui_story_5062_50620103_38_dialog_content = "Queijo! Ah, por que tem que ser queijo?! Miau!",
  ui_story_5062_50620103_39_dialog_content = "Philyshy, por favor, não desperdice nossos suprimentos!",
  ui_story_5062_50620103_40_dialog_content = "Essa equipe é bem animada! Me lembra aqueles dias com as Forças de Pedra.",
  ui_story_5062_50620103_41_dialog_content = "Naquela época, eu era como eles são agora... Hmm, qual é a palavra... isso mesmo—selvagem!",
  ui_story_5062_50620103_42_dialog_content = "Mantenha contato regular a cada hora e relate a chegada no ponto alvo ou se surgir alguma outra situação.",
  ui_story_5062_50620103_43_dialog_content = "Tudo bem, nós já passamos por tudo isso bem antes da missão.",
  ui_story_5062_50620103_44_dialog_content = "Sabemos quase nada sobre o que pode estar nos esperando além da linha de defesa. Mantenha-se vigilante.",
  ui_story_5062_50620103_45_dialog_content = "Entendi. Só queria que pudéssemos acabar com isso em vez de ficar ouvindo você falar sem parar...",
  ui_story_5062_50620103_46_dialog_content = "Farei o meu melhor para abandonar esses velhos hábitos... Não vou deixar o que aconteceu antes acontecer novamente.",
  ui_story_5062_50620103_47_dialog_content = "Desculpe colocá-lo nesta missão. É meio que improvisar.",
  ui_story_5062_50620103_48_dialog_content = "Poucas pessoas são competentes o suficiente para serem enviadas à fronteira. Eu simplesmente não tinha muita escolha.",
  ui_story_5062_50620103_49_dialog_content = "Tudo bem. Sou um soldado. O campo de batalha é minha casa.",
  ui_story_5062_50620103_50_dialog_content = "E chega de conversa fiada. A julgar pela diminuição da luz no ambiente, eu diria que entramos na área da missão.",
  ui_story_5062_50620103_51_dialog_content = "Fique atento a movimentos ao seu redor. Vou sincronizar as coordenadas do primeiro ponto alvo com você.",
  ui_story_5062_50620103_52_dialog_content = "Entendi.",
  ui_story_5062_50620103_53_dialog_content = "Senhorita Oficial de Inteligência, confirme sua informação sobre o ponto alvo, por favor.",
  ui_story_5062_50620103_54_dialog_content = "Como é que ainda temos que trabalhar quando nem temos peixe seco, miau...?",
  ui_story_5062_50620103_55_dialog_content = "Visual do local do alvo obtido. Pronto para iniciar a missão de exploração.",
  ui_story_5062_50620103_56_dialog_content = "Chegamos? Deixe-me assumir a liderança então!",
  ui_story_5062_50620103_57_dialog_content = "O quê?! Se alguém for ser capitão, serei eu! Que tal lutarmos por isso?",
  ui_story_5062_50620103_58_dialog_content = "Obviamente, o Sr. Gram é o capitão... Curo, você não consegue impedi-los?",
  ui_story_5062_50620103_59_dialog_content = "Não tenho nada a ver com esses idiotas...",
  ui_story_5062_50620103_60_dialog_content = "Gram, só mais uma coisa.",
  ui_story_5062_50620103_61_dialog_content = "Prossiga, Grande Marechal.",
  ui_story_5062_50620103_62_dialog_content = "... Ser capitão deste esquadrão não é um trabalho fácil. Obrigado."
}
return config
